// Generated by `cargo xtask add-card`.
// Round-trip regression test for the generated test suite.
//
// Card           : Raging River
// Set            : lea
// Collector #    : 168

#[test]
fn round_trip() {
    let text = "Whenever one or more creatures you control attack, each defending player divides all creatures without flying they control into a \"left\" pile and a \"right\" pile. Then, for each attacking creature you control, choose \"left\" or \"right.\" That creature can't be blocked this combat except by creatures with flying and creatures in a pile with the chosen label.";
    let ast = mtg_grammar::parse(text).expect("parse");
    let reprinted = mtg_grammar::unparse(&ast);
    assert_eq!(
        reprinted, text,
        "unparse must preserve the normalized oracle text"
    );
    let ast2 = mtg_grammar::parse(&reprinted).expect("reparse");
    assert_eq!(ast, ast2);
}
